const crypto = require('crypto');

const token = ($json.headers.authorization ?? '').replace(/^Bearer /i, '');
const [encodedHeader, encodedPayload, signature] = token.split('.');
if (!signature) throw new Error('Pedido sem token OIDC do Pub/Sub');

const header = JSON.parse(Buffer.from(encodedHeader, 'base64url').toString());
const claims = JSON.parse(Buffer.from(encodedPayload, 'base64url').toString());

const { keys } = await this.helpers.httpRequest({ url: 'https://www.googleapis.com/oauth2/v3/certs', json: true });
const jwk = keys.find((key) => key.kid === header.kid);
const signed =
  header.alg === 'RS256' &&
  jwk !== undefined &&
  crypto.verify(
    'RSA-SHA256',
    Buffer.from(`${encodedHeader}.${encodedPayload}`),
    crypto.createPublicKey({ key: jwk, format: 'jwk' }),
    Buffer.from(signature, 'base64url'),
  );

const trusted =
  signed &&
  ['https://accounts.google.com', 'accounts.google.com'].includes(claims.iss) &&
  claims.aud === $env.PUBSUB_PUSH_AUDIENCE &&
  claims.email === $env.PUBSUB_PUSH_SERVICE_ACCOUNT &&
  claims.email_verified === true &&
  claims.exp * 1000 > Date.now();
if (!trusted) throw new Error('Token OIDC do Pub/Sub invalido');

const { emailAddress, historyId } = JSON.parse(Buffer.from($json.body.message.data, 'base64').toString());
return { json: { emailAddress, historyId: String(historyId) } };

const crypto = require('crypto');

const account = $input.first().json;
const notification = $('Descodificar notificacao').first().json;

const decrypt = (encrypted) => {
  const key = Buffer.from($env.TOKEN_ENCRYPTION_KEY, 'base64');
  const raw = Buffer.from(encrypted, 'base64');
  const decipher = crypto.createDecipheriv('aes-256-gcm', key, raw.subarray(0, 12));
  decipher.setAuthTag(raw.subarray(12, 28));
  return Buffer.concat([decipher.update(raw.subarray(28)), decipher.final()]).toString('utf8');
};

const asJson = (res) => (typeof res === 'string' ? JSON.parse(res) : res);

const tokenRes = asJson(await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://oauth2.googleapis.com/token',
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body: 'client_id=' + encodeURIComponent($env.GOOGLE_CLIENT_ID) + '&client_secret=' + encodeURIComponent($env.GOOGLE_CLIENT_SECRET) + '&refresh_token=' + encodeURIComponent(decrypt(account.refresh_token)) + '&grant_type=refresh_token',
}));
const auth = { Authorization: 'Bearer ' + tokenRes.access_token };

const gmail = async (path, qs) => asJson(await this.helpers.httpRequest({ url: 'https://gmail.googleapis.com/gmail/v1/users/me/' + path, qs, headers: auth }));

const messageIds = new Set();
let newHistoryId = notification.historyId;
try {
  let pageToken;
  do {
    const page = await gmail('history', { startHistoryId: account.last_history_id || notification.historyId, historyTypes: 'messageAdded', labelId: 'INBOX', pageToken });
    for (const entry of page.history || []) {
      for (const added of entry.messagesAdded || []) messageIds.add(added.message.id);
    }
    newHistoryId = page.historyId || newHistoryId;
    pageToken = page.nextPageToken;
  } while (pageToken);
} catch (error) {
  // 404: o last_history_id guardado ja e antigo de mais, resta continuar a partir do historyId da notificacao.
  if (error.status !== 404) throw error;
}

const decodeBody = (data) => Buffer.from(data, 'base64url').toString('utf8');
const findPart = (payload, mime) => {
  if (payload.mimeType === mime && payload.body?.data) return payload.body.data;
  for (const part of payload.parts || []) {
    const found = findPart(part, mime);
    if (found) return found;
  }
  return null;
};

const items = [];
for (const id of messageIds) {
  const msg = await gmail('messages/' + id, { format: 'full' });
  // O filtro do history.list deixa escapar respostas enviadas na mesma conversa; a etiqueta da mensagem e que decide.
  if (!(msg.labelIds || []).includes('INBOX')) continue;
  const header = (name) => msg.payload.headers.find((h) => h.name.toLowerCase() === name)?.value ?? '';
  const plain = findPart(msg.payload, 'text/plain');
  const html = plain ? null : findPart(msg.payload, 'text/html');
  const body = plain ? decodeBody(plain) : html ? decodeBody(html).replace(/<[^>]+>/g, ' ') : msg.snippet;
  items.push({ json: {
    account_id: account.id,
    user_id: account.user_id,
    gmail_message_id: msg.id,
    sender: header('from'),
    subject: header('subject'),
    body,
    received_at: new Date(Number(msg.internalDate)).toISOString(),
    new_history_id: String(newHistoryId),
  } });
}

// Sem mensagens novas continua a valer a pena avancar o ponteiro, senao um 404 deixava a conta presa no mesmo historyId.
return items.length ? items : [{ json: { new_history_id: String(newHistoryId) } }];

const email = $json;
const prompt = 'Es o assistente de triagem de uma inbox de email. Analisa o email seguinte e devolve JSON com tres campos: summary (resumo do email em portugues de Portugal, uma ou duas frases), suggested_reply (resposta sugerida em portugues de Portugal, pronta a enviar, adequada ao tom do email), category (alta, media ou baixa). Usa alta para emails urgentes, com pedidos de acao concretos, ou respostas a uma conversa em curso; baixa para newsletters, notificacoes automaticas e marketing; media para o resto.\n\nDe: ' + email.sender + '\nAssunto: ' + email.subject + '\n\n' + String(email.body || '').slice(0, 8000);

const res = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-3.5-flash-lite:generateContent',
  headers: { 'x-goog-api-key': $env.GEMINI_API_KEY, 'Content-Type': 'application/json' },
  body: JSON.stringify({
    contents: [{ parts: [{ text: prompt }] }],
    generationConfig: {
      responseMimeType: 'application/json',
      responseSchema: {
        type: 'OBJECT',
        properties: {
          summary: { type: 'STRING' },
          suggested_reply: { type: 'STRING' },
          category: { type: 'STRING', enum: ['alta', 'media', 'baixa'] },
        },
        required: ['summary', 'suggested_reply', 'category'],
      },
    },
  }),
});
const parsed = typeof res === 'string' ? JSON.parse(res) : res;
const out = JSON.parse(parsed.candidates[0].content.parts[0].text);
return { json: { ...email, ai_summary: out.summary, ai_suggested_reply: out.suggested_reply, ai_category: out.category } };

const emails = $('Analisar com Gemini').all().map((item) => item.json);
const rules = $input.all().map((item) => item.json).filter((rule) => rule.condition_type);

const SPECIFICITY = { remetente: 0, dominio: 1, palavra_chave: 2 };
const senderAddress = (sender) => ((sender.match(/<(.+)>/) || [])[1] || sender).trim().toLowerCase();
const matches = (rule, email) => {
  const value = rule.condition_value.trim().toLowerCase();
  if (rule.condition_type === 'remetente') return senderAddress(email.sender) === value;
  if (rule.condition_type === 'dominio') return senderAddress(email.sender).endsWith('@' + value);
  return (email.subject || '').toLowerCase().includes(value);
};

return emails.map((email) => {
  const winner = rules
    .filter((rule) => matches(rule, email))
    .sort((a, b) => SPECIFICITY[a.condition_type] - SPECIFICITY[b.condition_type] || (a.created_at < b.created_at ? -1 : 1))[0];
  return { json: { ...email, category: winner ? winner.forced_category : email.ai_category } };
});
